template:
// Smallest x in [lo, hi] with feasible(x) == true, given feasible is monotone N...NY...Y.
// Precondition: feasible(hi) is true. Returns hi if nothing smaller works.
template <class F>
long long firstTrue(long long lo, long long hi, F feasible) {
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;      // rounds down → never re-tests hi
        if (feasible(mid)) hi = mid;             // mid works: answer is mid or smaller
        else lo = mid + 1;                       // mid fails: answer is strictly larger
    }
    return lo;
}

// Example: minimum ship capacity to deliver all weights within D days.
int shipWithinDays(const vector<int>& w, int D) {
    long long lo = *max_element(w.begin(), w.end());   // must carry the heaviest item
    long long hi = accumulate(w.begin(), w.end(), 0LL); // one trip carries everything
    auto feasible = [&](long long cap) {
        int days = 1; long long load = 0;
        for (int x : w) {
            if (load + x > cap) { ++days; load = 0; }   // start a new day
            load += x;
        }
        return days <= D;
    };
    return (int)firstTrue(lo, hi, feasible);
}

